CREATE FUNCTION public.sandy_system_metadata_registry_rows(p_args jsonb,p_api_only boolean)
RETURNS TABLE(operation text,domain text,permission_scope text,is_mutation boolean,handler text,api_exposed boolean,ai_exposed boolean,verified boolean,last_verified_at timestamptz,implementation_state text)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
 SELECT r.operation,coalesce(r.domain,'unknown'),coalesce(r.permission_scope,'unknown'),r.is_mutation,coalesce(r.handler,'unassigned'),r.api_exposed,r.ai_exposed,r.verified,r.last_verified_at,coalesce(r.implementation_state,'unassessed')
 FROM public.sandy_operation_registry r WHERE(NOT p_api_only OR r.api_exposed)
 AND(p_args->>'domain' IS NULL OR r.domain=p_args->>'domain')
 AND(p_args->>'search' IS NULL OR strpos(lower(r.operation||' '||coalesce(r.domain,'')),lower(p_args->>'search'))>0)
 AND(p_args->>'verified' IS NULL OR r.verified=(p_args->>'verified')::boolean)
 AND(p_args->>'is_mutation' IS NULL OR r.is_mutation=(p_args->>'is_mutation')::boolean)
$$;
CREATE FUNCTION public.sandy_system_metadata_execute(p_operation text,p_arguments jsonb,p_canonical_arguments text,p_canonical_scope text,p_actor_id uuid,p_request_id uuid,p_admission_id uuid,p_grant_id uuid,p_channel text DEFAULT 'api') RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE admission public.sandy_api_execution_admissions%ROWTYPE;registry public.sandy_operation_registry%ROWTYPE;config jsonb;proof jsonb;expected_scope jsonb;input_hash text;items jsonb:='[]';item jsonb;cursor jsonb;result jsonb;more boolean:=false;lim integer:=coalesce((p_arguments->>'limit')::integer,50);last_row jsonb;scope_fingerprint text;after_checked timestamptz;
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' THEN RETURN jsonb_build_object('ok',false,'error','internal_service_transport_required','http_status',403,'executed',false);END IF;
 SELECT c.contract INTO config FROM public.sandy_system_metadata_contracts c WHERE c.operation=p_operation;
 IF config IS NULL OR p_request_id IS NULL OR p_actor_id IS NULL OR p_channel NOT IN('api','mcp') OR p_channel IS NULL OR octet_length(p_canonical_arguments)>30000 OR p_canonical_arguments::jsonb IS DISTINCT FROM p_arguments OR NOT public.sandy_product_input_valid(config->'input_schema',p_arguments) THEN RETURN jsonb_build_object('ok',false,'error','invalid_system_metadata_arguments','http_status',400,'executed',false);END IF;
 SELECT * INTO admission FROM public.sandy_api_execution_admissions WHERE id=p_admission_id FOR UPDATE;
 SELECT * INTO registry FROM public.sandy_operation_registry WHERE operation=p_operation FOR SHARE;
 IF admission.id IS NULL OR admission.grant_id IS DISTINCT FROM p_grant_id OR admission.actor_id IS DISTINCT FROM p_actor_id OR admission.request_id IS DISTINCT FROM p_request_id OR admission.operation IS DISTINCT FROM p_operation OR admission.principal_kind IS DISTINCT FROM 'auth_user' OR admission.tenant_id IS NOT NULL OR admission.credential_id IS NOT NULL OR admission.customer_key_id IS NOT NULL OR admission.is_mutation OR admission.state<>'admitted' OR NOT public.sandy_api_current_owner(p_actor_id) OR NOT EXISTS(SELECT 1 FROM auth.users u WHERE u.id=p_actor_id AND u.email_confirmed_at IS NOT NULL AND NOT coalesce(u.is_anonymous,false)) THEN RETURN jsonb_build_object('ok',false,'error','genuine_current_owner_admission_required','http_status',403,'executed',false);END IF;
 IF registry.handler IS DISTINCT FROM 'sandy-system-metadata-api' OR registry.permission_scope IS DISTINCT FROM 'system:read' OR registry.is_mutation OR registry.api_exposed IS DISTINCT FROM true OR(p_channel='mcp' AND registry.ai_exposed IS DISTINCT FROM true) OR registry.verified IS DISTINCT FROM true OR registry.input_schema IS DISTINCT FROM config->'input_schema' OR registry.output_schema IS DISTINCT FROM config->'output_schema' OR registry.error_contract->>'contract_sha256' IS DISTINCT FROM config->>'contract_sha256' OR registry.error_contract->>'requires_approval' IS DISTINCT FROM config->>'requires_approval' OR registry.error_contract->>'requires_real_user_session' IS DISTINCT FROM 'true' OR registry.error_contract->>'api_key_delegable' IS DISTINCT FROM 'false' OR admission.contract_sha256 IS DISTINCT FROM config->>'contract_sha256' OR admission.registry_revision_sha256 IS DISTINCT FROM public.sandy_api_registry_revision(p_operation) THEN RETURN jsonb_build_object('ok',false,'error','system_metadata_contract_or_exposure_changed','http_status',409,'executed',false);END IF;
 expected_scope:=jsonb_build_object('sandy_project_ref','zmqlyygzqoidkcwdysok','permission_scope','system:read','service','system_metadata_v1');
 IF p_operation='system.connections' THEN expected_scope:=expected_scope||jsonb_build_object('customer_id',(p_arguments->>'customer_id')::uuid::text);END IF;
 input_hash:=encode(extensions.digest(p_canonical_arguments,'sha256'),'hex');
 IF p_canonical_scope::jsonb IS DISTINCT FROM expected_scope OR admission.scope_sha256 IS DISTINCT FROM encode(extensions.digest(p_canonical_scope,'sha256'),'hex') OR admission.input_sha256 IS DISTINCT FROM input_hash THEN RETURN jsonb_build_object('ok',false,'error','system_metadata_exact_scope_required','http_status',403,'executed',false);END IF;
 proof:=public.sandy_api_consume_execution_grant(p_grant_id,p_actor_id,NULL,p_operation,input_hash,p_request_id,admission.contract_sha256,admission.scope_sha256);IF proof->>'allowed' IS DISTINCT FROM 'true' THEN RETURN proof;END IF;
 IF p_operation IN('system.catalog','system.operation_catalog','system.coverage') THEN
  IF p_operation='system.coverage' THEN
   SELECT jsonb_build_object('registered',count(*),'verified',count(*)FILTER(WHERE q.verified),'unverified',count(*)FILTER(WHERE NOT q.verified),'api_exposed',count(*)FILTER(WHERE q.api_exposed),'ai_exposed',count(*)FILTER(WHERE q.ai_exposed),'registry_flags_complete',count(*)>0 AND bool_and(q.verified AND q.api_exposed AND q.ai_exposed),'original_161_completion_not_established',true,'count_scope','filtered_registry') INTO item FROM public.sandy_system_metadata_registry_rows(p_arguments,false)q;
  END IF;
  SELECT coalesce(jsonb_agg(CASE WHEN p_operation='system.coverage' THEN jsonb_build_object('operation',q.operation,'api_exposed',q.api_exposed,'ai_exposed',q.ai_exposed,'verified',q.verified) ELSE to_jsonb(q) END ORDER BY q.operation),'[]') INTO items FROM(SELECT * FROM public.sandy_system_metadata_registry_rows(p_arguments,p_operation='system.operation_catalog')r WHERE(p_arguments->>'after_operation' IS NULL OR r.operation>p_arguments->>'after_operation') AND(p_operation<>'system.coverage' OR NOT r.verified) ORDER BY r.operation LIMIT lim+1)q;
  more:=jsonb_array_length(items)>lim;IF more THEN items:=items-lim;cursor:=to_jsonb(items->-1->>'operation');END IF;
 ELSIF p_operation IN('system.capabilities','system.runtime') THEN
  IF p_arguments->'cursor'->>'checked_at' IS NOT NULL AND p_arguments->'cursor'->>'checked_at'<>'none' THEN after_checked:=(p_arguments->'cursor'->>'checked_at')::timestamptz;END IF;
  IF p_operation='system.capabilities' THEN
   SELECT coalesce(jsonb_agg(to_jsonb(q) ORDER BY q.feature_key,q.scope_fingerprint,q.channel),'[]') INTO items FROM(
    SELECT r.feature_key,encode(extensions.digest(r.scope_key,'sha256'),'hex') AS scope_fingerprint,r.channel,r.deployment_version,r.implementation_state,r.auth_state,r.health_state,r.checked_at,false AS provider_verified FROM public.sandy_capability_runtime_state r
    WHERE(p_arguments->>'feature_key' IS NULL OR r.feature_key=p_arguments->>'feature_key') AND(p_arguments->>'channel' IS NULL OR r.channel=p_arguments->>'channel') AND(p_arguments->>'health_state' IS NULL OR r.health_state=p_arguments->>'health_state') AND(p_arguments->>'checked_after' IS NULL OR r.checked_at>=(p_arguments->>'checked_after')::timestamptz)
    AND(p_arguments->'cursor' IS NULL OR(r.feature_key,encode(extensions.digest(r.scope_key,'sha256'),'hex'),r.channel)>(p_arguments->'cursor'->>'feature_key',p_arguments->'cursor'->>'scope_fingerprint',p_arguments->'cursor'->>'channel')) ORDER BY r.feature_key,encode(extensions.digest(r.scope_key,'sha256'),'hex'),r.channel LIMIT lim+1)q;
  ELSE
   SELECT coalesce(jsonb_agg(to_jsonb(q) ORDER BY q.checked_at DESC NULLS LAST,q.feature_key,q.scope_fingerprint,q.channel),'[]') INTO items FROM(
    SELECT r.feature_key,encode(extensions.digest(r.scope_key,'sha256'),'hex') AS scope_fingerprint,r.channel,r.deployment_version,r.implementation_state,r.auth_state,r.health_state,r.checked_at,false AS provider_verified FROM public.sandy_capability_runtime_state r
    WHERE(p_arguments->>'feature_key' IS NULL OR r.feature_key=p_arguments->>'feature_key') AND(p_arguments->>'channel' IS NULL OR r.channel=p_arguments->>'channel') AND(p_arguments->>'health_state' IS NULL OR r.health_state=p_arguments->>'health_state') AND(p_arguments->>'checked_after' IS NULL OR r.checked_at>=(p_arguments->>'checked_after')::timestamptz)
    AND(p_arguments->'cursor' IS NULL OR coalesce(r.checked_at,'-infinity'::timestamptz)<coalesce(after_checked,'-infinity'::timestamptz) OR(coalesce(r.checked_at,'-infinity'::timestamptz)=coalesce(after_checked,'-infinity'::timestamptz) AND(r.feature_key,encode(extensions.digest(r.scope_key,'sha256'),'hex'),r.channel)>(p_arguments->'cursor'->>'feature_key',p_arguments->'cursor'->>'scope_fingerprint',p_arguments->'cursor'->>'channel'))) ORDER BY r.checked_at DESC NULLS LAST,r.feature_key,encode(extensions.digest(r.scope_key,'sha256'),'hex'),r.channel LIMIT lim+1)q;
  END IF;
  more:=jsonb_array_length(items)>lim;IF more THEN items:=items-lim;last_row:=items->-1;cursor:=jsonb_build_object('feature_key',last_row->>'feature_key','scope_fingerprint',last_row->>'scope_fingerprint','channel',last_row->>'channel');IF p_operation='system.runtime' THEN cursor:=cursor||jsonb_build_object('checked_at',coalesce(last_row->>'checked_at','none'));END IF;END IF;
 ELSIF p_operation='system.connections' THEN
  IF NOT EXISTS(SELECT 1 FROM public.email_customers c WHERE c.id=(p_arguments->>'customer_id')::uuid) THEN RAISE EXCEPTION 'metadata_target_not_found' USING ERRCODE='P0404';END IF;
  SELECT coalesce(jsonb_agg(to_jsonb(q) ORDER BY q.connection_fingerprint),'[]') INTO items FROM(
   SELECT encode(extensions.digest(c.connected_account_id,'sha256'),'hex') AS connection_fingerprint,c.toolkit_slug AS provider,c.status AS recorded_status,c.company_id,c.updated_at,false AS provider_verified FROM public.sandy_composio_connections c
   WHERE c.customer_id=(p_arguments->>'customer_id')::uuid AND(p_arguments->>'company_id' IS NULL OR c.company_id=(p_arguments->>'company_id')::uuid) AND(p_arguments->>'provider' IS NULL OR c.toolkit_slug=p_arguments->>'provider') AND(p_arguments->>'status' IS NULL OR c.status=p_arguments->>'status') AND(p_arguments->>'after_fingerprint' IS NULL OR encode(extensions.digest(c.connected_account_id,'sha256'),'hex')>p_arguments->>'after_fingerprint') ORDER BY encode(extensions.digest(c.connected_account_id,'sha256'),'hex') LIMIT lim+1)q;
  more:=jsonb_array_length(items)>lim;IF more THEN items:=items-lim;cursor:=to_jsonb(items->-1->>'connection_fingerprint');END IF;
 ELSIF p_operation='system.operation_status' THEN
  item:=public.sandy_api_get_execution_receipt(p_actor_id,(p_arguments->>'request_id')::uuid,NULL);IF item->>'ok' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'metadata_receipt_not_found' USING ERRCODE='P0404';END IF;
 ELSE RAISE EXCEPTION 'unsupported_metadata_operation' USING ERRCODE='22023';END IF;
 result:=jsonb_build_object('items',items,'item',item,'next_cursor',cursor,'possibly_truncated',more,'source','recorded_metadata','provider_verified',false,'executability_not_implied',true,'schemas_via','Sandy API describe','notice',CASE WHEN p_operation='system.runtime' THEN 'Recorded runtime evidence can be stale; it does not attest this request deployed code or current provider connectivity.' WHEN p_operation='system.connections' THEN 'Exact owner-approved customer inventory only; provider handles, credentials, scopes and live readiness are excluded.' WHEN p_operation='system.coverage' THEN 'Registry flag counts do not establish completion of the original161 requirements.' WHEN p_operation='system.operation_status' THEN 'Existing owner receipt only; no operation is admitted again or redispatched.' ELSE 'Recorded metadata only; registration and deployment flags do not prove successful execution. Schemas remain in authorized Sandy API describe.' END);
 IF octet_length(result::text)>250000 THEN RAISE EXCEPTION 'metadata_response_too_large' USING ERRCODE='22023';END IF;
 proof:=public.sandy_api_finish_execution(admission.id,'succeeded',NULL,NULL,encode(extensions.digest(result::text,'sha256'),'hex'));IF proof->>'ok' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'metadata_receipt_finish_failed';END IF;
 RETURN jsonb_build_object('ok',true,'operation',p_operation,'contract_version','1.0.0','admission_id',admission.id,'request_id',admission.request_id,'request_state','observed','executed',true,'result',result,'reconciliation_required',false);
EXCEPTION WHEN SQLSTATE 'P0404' THEN RETURN jsonb_build_object('ok',false,'error','system_metadata_target_or_receipt_not_found','http_status',404,'executed',false);
 WHEN data_exception THEN RETURN jsonb_build_object('ok',false,'error','invalid_system_metadata_arguments_or_response_size','http_status',400,'executed',false);
END $$;
REVOKE ALL ON FUNCTION public.sandy_system_metadata_registry_rows(jsonb,boolean),public.sandy_system_metadata_execute(text,jsonb,text,text,uuid,uuid,uuid,uuid,text) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.sandy_system_metadata_execute(text,jsonb,text,text,uuid,uuid,uuid,uuid,text) TO service_role;

COMMIT;
